def repost_future_sle_and_gle(self, force=False, via_landed_cost_voucher=False):
	args = frappe._dict(
		{
			"posting_date": self.posting_date,
			"posting_time": self.posting_time,
			"voucher_type": self.doctype,
			"voucher_no": self.name,
			"company": self.company,
			"via_landed_cost_voucher": via_landed_cost_voucher,
		}
	)

	if self.docstatus == 2:
		force = True

	if force or future_sle_exists(args, for_update=True) or repost_required_for_queue(self):
		item_based_reposting = frappe.get_single_value("Stock Reposting Settings", "item_based_reposting")
		if item_based_reposting:
			create_item_wise_repost_entries(
				voucher_type=self.doctype,
				voucher_no=self.name,
				via_landed_cost_voucher=via_landed_cost_voucher,
			)
		else:
			create_repost_item_valuation_entry(args)

def repost(doc):
	try:
		frappe.flags.through_repost_item_valuation = True
		if not frappe.db.exists("Repost Item Valuation", doc.name):
			return

		# This is to avoid TooManyWritesError in case of large reposts
		frappe.db.MAX_WRITES_PER_TRANSACTION *= 4

		doc.set_status("In Progress")
		if not frappe.in_test:
			frappe.db.commit()

		if (
			doc.voucher_type in ["Purchase Receipt", "Purchase Invoice", "Stock Entry"]
			and doc.recalculate_valuation_rate
		):
			doc._recalculate_valuation_rate()

		if doc.recreate_stock_ledgers:
			doc.recreate_stock_ledger_entries()

		if not doc.repost_only_accounting_ledgers:
			repost_sl_entries(doc)

		repost_gl_entries(doc)

		doc.set_status("Completed")
		doc.db_set("reposting_data_file", None)
		remove_attached_file(doc.name)

	except Exception as e:
		if frappe.in_test:
			# Don't silently fail in tests,
			# there is no reason for reposts to fail in CI
			raise

		frappe.db.rollback()
		traceback = frappe.get_traceback()
		doc.log_error("Unable to repost item valuation")

		message = frappe.message_log.pop() if frappe.message_log else ""
		if isinstance(message, dict):
			message = message.get("message")

		status = "Failed"
		# If failed because of a recoverable error (timeout, deadlock), set status to In Progress
		# so the scheduler automatically retries instead of leaving it permanently failed.
		# NOTE: isinstance check comes first because the traceback string matching is unreliable
		# when SIGALRM kills the process mid-C-extension (JobTimeoutException may not appear
		# in the traceback if the exception handler itself was interrupted).
		traceback_lower = traceback.lower() if traceback else ""
		if isinstance(e, RecoverableErrors) or (
			traceback_lower and ("timeout" in traceback_lower or "deadlock found" in traceback_lower)
		):
			status = "In Progress"

		if traceback:
			message += "<br><br>" + "<b>Traceback:</b> <br>" + traceback

		frappe.db.set_value(
			doc.doctype,
			doc.name,
			{
				"error_log": message,
				"status": status,
			},
		)

		if status == "Failed":
			outgoing_email_account = frappe.get_cached_value(
				"Email Account", {"default_outgoing": 1, "enable_outgoing": 1}, "name"
			)

			if outgoing_email_account and not isinstance(e, RecoverableErrors):
				notify_error_to_stock_managers(doc, message)
				doc.set_status("Failed")
	finally:
		if not frappe.in_test:
			frappe.db.commit()

def clear_doctype_cache(doctype=None):
	clear_controller_cache(doctype)
	frappe.client_cache.erase_persistent_caches(doctype=doctype)

	if doctype:
		frappe.local.valid_columns.pop(doctype, None)
	else:
		frappe.local.valid_columns = {}

	_clear_doctype_cache_from_redis(doctype)
	if hasattr(frappe.db, "after_commit"):
		frappe.db.after_commit.add(lambda: _clear_doctype_cache_from_redis(doctype))
		frappe.db.after_rollback.add(lambda: _clear_doctype_cache_from_redis(doctype))

def notify_update(self):
	"""Publish realtime that the current document is modified"""
	if (
		frappe.flags.in_import
		or frappe.flags.in_patch
		or frappe.flags.in_migrate
		or frappe.flags.in_install
	):
		return

	frappe.publish_realtime(
		"doc_update",
		{"modified": self.modified, "doctype": self.doctype, "name": self.name},
		doctype=self.doctype,
		docname=self.name,
		after_commit=True,
	)

	if not self.meta.get("read_only") and not self.meta.get("issingle") and not self.meta.get("istable"):
		data = {"doctype": self.doctype, "name": self.name, "user": frappe.session.user}
		frappe.publish_realtime("list_update", data, after_commit=True)

def _add_webhook_to_queue(webhook, doc):
	# Maintain a queue and flush on commit
	if not getattr(frappe.local, "_webhook_queue", None):
		frappe.local._webhook_queue = []
		frappe.db.after_commit.add(flush_webhook_execution_queue)

	frappe.local._webhook_queue.append(frappe._dict(doc=doc, webhook=webhook))
